//! Kimchi's Poseidon constants over `Fq`, transcribed from
//! o1-labs/proof-systems `poseidon/src/pasta/fq_kimchi.rs` ("Generated by
//! ./params.sage --rounds 55 rust 3 kimchi"), the decimal strings there
//! written as canonical little-endian 64-bit limbs.

use arrabbiata_pasta::Fq;

use super::ROUNDS;

/// A canonical element, checked below the modulus at compile time.
const fn e(limbs: [u64; 4]) -> Fq {
    match Fq::from_canonical_limbs(limbs) {
        Some(x) => x,
        None => panic!("a Kimchi constant is below the modulus"),
    }
}

